#!/usr/bin/env python3
# 產生 renderer/src/behavior/names_more_langs.json：C#、Ruby、Lua 的「呼叫名稱 → 行為分類」名稱表與 API 語意，
# 並補強 Python、Java、JavaScript（原本的表很稀疏：Python 沒有時間／記錄／結構化資料／檔案系統…）。
# 用法：python scripts/gen-name-tables-more.py（改了這裡就重跑，再 node scripts/embed-code-ui.js）。
# 名稱的寫法（要跟引擎的呼叫名稱候選一致，見 engine_1_core.js 的 csCallCandidates／rubyCallCandidates／luaCallCandidates／pythonCallCandidates／javaCallCandidates／jsCallCandidates）：
#   C#     ：靜態呼叫 File.ReadAllText、Console.WriteLine；實例方法 .GetAsync（任何接收者）；建構子 new Thread(…) → Thread；泛型會去掉。
#   Ruby   ：File.read、Net::HTTP.get（也比對最後兩段 HTTP.get）、.each（任何接收者）、沒有接收者的 puts／system／raise；反引號 → `。
#   Lua    ：io.open、os.execute（冒號呼叫 f:read 會變成 f.read，也比對 .read）、沒有接收者的 print／pcall／require。
#   Python ：os.path.exists（也比對最後兩段 path.exists 與最後一段 exists）、logger.info、沒有接收者的 print／open。
#   Java   ：Files.readAllLines、System.out.println、LOG.info（也比對最後一段方法名）。
#   JS     ：fs.readFileSync、console.log、fetch、new Date → Date（也比對最後一段）。
# 這些名稱是依官方文件知識整理，沒有逐條對照官方文件；有錯用 behavior_define 修正。
# 與既有的表（behavior_patterns.json、names_cpp_rust_go.json）重複、但分類不同的名稱會被略過（以既有的為準），並在最後列出。
import json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
BEH = os.path.join(HERE, '..', 'renderer', 'src', 'behavior')

def L(s):
    return [x for x in s.split() if x]

C = {}   # category -> {lang: [names]}
def add(cat, lang, names):
    C.setdefault(cat, {}).setdefault(lang, [])
    for n in L(names):
        if n not in C[cat][lang]:
            C[cat][lang].append(n)

API = {}
def api(lang, name, summary, params=None, ret=None, rules=None):
    e = {'summary': summary, 'parameters': [{'name': n, 'meaning': m} for n, m in (params or [])]}
    if ret:
        e['return'] = {'meaning': ret}
        if rules:
            e['return']['rules'] = [{'when': {'op': op, 'value': v}, 'meaning': m} for op, v, m in rules]
    API.setdefault(lang, {})[name] = e

